```move
/// DigiShield v3 difficulty adjustment (used by Zcash)
/// Adjusts difficulty every block based on:
/// - averaging_window = 17 blocks
/// - Uses median timestamps for stability
/// - Damping factor of 4 to prevent oscillation

public fun calc_next_difficulty(
    params: &Params,
    last_block_time: u32,
    last_block_bits: u32,
    avg_target: u256,       // Average target over window
    median_time_past: u64,  // Median of last 11 timestamps
    median_time_first: u64, // Median timestamp at start of averaging window
): u32 {
    // Calculate actual timespan
    let actual_timespan = median_time_past - median_time_first;

    // Apply damping factor
    let target_timespan = params.target_spacing() * params.averaging_window();
    let damped_timespan = actual_timespan + 3 * target_timespan;
    let actual_timespan_damped = damped_timespan / 4;

    // Clamp to min/max (0.75x to 1.25x)
    let min_timespan = target_timespan * 3 / 4;  // 75%
    let max_timespan = target_timespan * 5 / 4;  // 125%
    let clamped_timespan = clamp(actual_timespan_damped, min_timespan, max_timespan);

    // Calculate new target
    let new_target = avg_target * clamped_timespan / target_timespan;
    target_to_bits(new_target)
}
```

