use zcash_lib::header::BlockHeader;
use zcash_lib::equihash;

/// For Zcash, pow_check verifies Equihash solution
public fun pow_check(header: &BlockHeader) {
    // Get header bytes (140 bytes without solution)
    let header_bytes = header.header_bytes();
    let nonce = header.nonce();
    let solution = header.solution();

    // Verify Equihash solution
    assert!(equihash::verify(&header_bytes, &nonce, &solution), EPoW);

    // Also verify block hash meets difficulty target
    let target = bits_to_target(header.bits());
    assert!(target >= to_u256(header.block_hash()), EPoW);
}
```

Key difference from Bitcoin: Equihash verification replaces simple SHA256d < target check.

