```move
public fun calc_next_required_difficulty(lc: &LightClient, parent_block: &LightBlock): u32 {
    let params = lc.params();

    // DigiShield adjusts every block (not just at retarget boundaries)
    if (params.pow_no_retargeting() || parent_block.height() == 0) {
        return params.power_limit_bits()
    };

    let averaging_window = params.averaging_window(); // 17 for Zcash

    // Need enough blocks for averaging window
    if (parent_block.height() < averaging_window) {
        return parent_block.header().bits()
    };

    // Compute average target over the averaging window
    let mut avg_target: u256 = 0;
    let mut i = 0;
    while (i < averaging_window) {
        let block = lc.relative_ancestor(parent_block, i);
        avg_target = avg_target + block.header().target();
        i = i + 1;
    };
    avg_target = avg_target / (averaging_window as u256);

    // Calculate median timestamps for timespan
    let median_time_past = calc_median_time(lc, parent_block);
    let first_block = lc.relative_ancestor(parent_block, averaging_window);
    let median_time_first = calc_median_time(lc, first_block);

    // Use zcash_spv::difficulty module for final calculation
    difficulty::calc_next_difficulty(params, avg_target, median_time_past, median_time_first)
}
```
This differs from Bitcoin which only adjusts every 2016 blocks. DigiShield adjusts every block to prevent difficulty oscillation attacks.

