Implement median time functions for Zcash:
```move
/// Calculate median time of past 11 blocks for timestamp validation
/// Same logic as Bitcoin - used to prevent timestamp manipulation
fun calc_past_median_time(lc: &LightClient, lb: &LightBlock): u32 {
    let median_time_blocks = 11;
    let mut timestamps = vector[];
    let mut i = 0;
    let mut prev_lb = lb;
    while (i < median_time_blocks) {
        timestamps.push_back(prev_lb.header().timestamp());
        if (!lc.exist(prev_lb.header().parent())) {
            break
        };
        prev_lb = lc.relative_ancestor(prev_lb, 1);
        i = i + 1;
    };
    let size = timestamps.length();
    nth_element(&mut timestamps, size / 2)
}

/// Calculate median time for DigiShield timespan calculation
/// Used at both endpoints of the averaging window
fun calc_median_time(lc: &LightClient, lb: &LightBlock): u64 {
    // DigiShield uses median_time_span (typically 11) for stability
    let median_time_span = lc.params().median_time_span();
    let mut timestamps = vector[];
    let mut i = 0;
    let mut prev_lb = lb;
    while (i < median_time_span && lc.exist(prev_lb.header().parent())) {
        timestamps.push_back(prev_lb.header().timestamp() as u64);
        prev_lb = lc.relative_ancestor(prev_lb, 1);
        i = i + 1;
    };
    let size = timestamps.length();
    nth_element_u64(&mut timestamps, size / 2)
}
```
Note: calc_median_time returns u64 for DigiShield timespan math, while calc_past_median_time returns u32 for direct timestamp comparison.

