public(package) fun parse_tx(r: &mut Reader): Transaction {
    // Read version as u32 (includes overwinter flag)
    let version_bytes = r.read(4);
    let version = le_bytes_to_u32(version_bytes);

    // Read version_group_id (Zcash-specific, 4 bytes)
    let vgid_bytes = r.read(4);
    let version_group_id = le_bytes_to_u32(vgid_bytes);

    // NO SegWit marker/flag check - Zcash doesn't use SegWit

    // Parse inputs (reuse bitcoin_lib::input::decode)
    let number_inputs = r.read_compact_size();
    let mut inputs = vector[];
    number_inputs.do!(|_| inputs.push_back(input::decode(r)));

    // Parse outputs (reuse bitcoin_lib::output::decode)
    let number_outputs = r.read_compact_size();
    let mut outputs = vector[];
    number_outputs.do!(|_| outputs.push_back(output::decode(r)));

    // NO witness data section

    let locktime = le_bytes_to_u32(r.read(4));
