use zcash_lib::blake2b;

/// Zcash tx_id personalization: 'ZcashTxHash' padded to 16 bytes
const TX_HASH_PERSONAL: vector<u8> = b"ZcashTxHash\x00\x00\x00\x00\x00"; // 16 bytes

/// Compute Zcash transaction ID using BLAKE2b-256 with personalization
public fun compute_tx_id(tx: &Transaction): vector<u8> {
    let preimage = serialize_for_txid(tx);
    blake2b::hash_with_personal(&preimage, TX_HASH_PERSONAL)
}

/// Serialize transaction for tx_id computation
/// Order: version || version_group_id || inputs || outputs || locktime || expiry_height
fun serialize_for_txid(tx: &Transaction): vector<u8> {
    let mut raw = vector[];
    raw.append(u32_to_le_bytes(tx.version));
    raw.append(u32_to_le_bytes(tx.version_group_id));
    raw.append(u64_to_varint_bytes(tx.inputs.length()));
    tx.inputs.do_ref!(|inp| raw.append(inp.encode()));
    raw.append(u64_to_varint_bytes(tx.outputs.length()));
    tx.outputs.do_ref!(|out| raw.append(out.encode()));
    raw.append(u32_to_le_bytes(tx.locktime));
    raw.append(u32_to_le_bytes(tx.expiry_height));
    raw
}
```

